#pragma once
#include <filesystem>
#include <string>
#include <vector>

namespace blitz::tools {
	/** All bytes of the file. Throws std::runtime_error if it can't be read.
	 */
	std::string read_file(std::filesystem::path const& file);

	/** All bytes of the standard input.
	 */
	std::string read_stdin();

	/** Every source file beneath the directory, sorted by path: The files that end in .bb (not case sensitive; .b3d is a model format as well).
	 * Links are not followed, to directories or to files. Throws std::runtime_error if the directory can't be read.
	 */
	std::vector<std::filesystem::path> find_sources(std::filesystem::path const& directory);

	/** Replace the contents of the file, all at once. Throws std::runtime_error if it can't be written.
	 */
	void write_file(std::filesystem::path const& file, std::string const& data);
} // namespace blitz::tools
